contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount <= 10);

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(
            (amount == 10 && !reverted && ((potAfter == 10 && cBalAfter == cBalBefore + 10) || (potAfter == 0 && cBalAfter == cBalBefore - potBefore)))
            ||
            (amount != 10 && reverted && potAfter == potBefore && cBalAfter == cBalBefore)
        );
    }

    receive() external payable {}
}

